try{const saved=localStorage.getItem(KEY);if(saved){const candidate=JSON.parse(saved);checkBackup(candidate);db=candidate;}}catch(e){storageOK=false;corruptStorage=true;}
let ui={route:location.hash.slice(1)||'dashboard',group:'pilotage',studyId:db.studies.find(s=>!s.archived)?.id||'',step:1,selectedPair:'',selectedRisk:'',path:'route2',view:'list',query:'',catalogKind:'value',scaleId:db.scales[0].id,importPrepared:false};
try{const prev=JSON.parse(localStorage.getItem(KEY+'-ui')||'null');if(prev&&db.studies.some(x=>x.id===prev.studyId)){ui.studyId=prev.studyId;ui.step=Math.max(1,Math.min(5,Number(prev.step)||1));}}catch(e){}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const NAMES={value:'Valeurs métier',asset:'Biens supports',supplier:'Fournisseurs',role:'Rôles',perimeter:'Périmètres',process:'Processus',source:'Sources de risque',objective:'Objectifs visés'};
