function genericForm(old){let route=ui.route;showForm(old?'Modifier la fiche':'Nouvelle fiche fictive',field('title','Libellé',old?.title)+field('owner','Responsable fictif',old?.owner||'Rôle RSSI démo')+field('status','État',old?.status||'Brouillon','text',['Brouillon','Planifié','En cours','Clos'])+field('description','Description',old?.description,'textarea'),f=>{db.records[route]||=[];if(old)Object.assign(old,f);else db.records[route].push({id:id('FIC'),...f});persist('Fiche de démonstration enregistrée',f.title);});}
function validateStep(){let s=requireStudy(),n=ui.step,errors=[];if(n>1&&!s.validated[n-1])errors.push('Validez d’abord l’atelier '+(n-1)+'.');if(n===1){if(!s.scope||!s.owner)errors.push('Choisissez le périmètre et le responsable.');if(!items('events').some(e=>e.valueId&&e.assetId&&e.justification.trim()))errors.push('Ajoutez un événement redouté lié à une valeur métier et un support, avec justification.');}if(n===2){let ps=items('pairs');if(!ps.length||!ps.some(p=>p.retained==='Oui'))errors.push('Retenez au moins un couple.');if(ps.some(p=>p.retained==='À examiner'||!p.activity.trim()||!p.justification.trim()))errors.push('Documentez l’activité et la décision de chaque couple.');}if(n===3&&(!items('strategies').length||items('strategies').some(x=>!items('pairs').some(p=>p.id===x.pairId&&p.retained==='Oui')||!items('events').some(e=>e.id===x.eventId)||!x.supplierId||!x.description.trim())))errors.push('Chaque scénario doit relier un couple retenu, une partie prenante et un événement de cette étude.');if(n===4&&(!items('operations').length||items('operations').some(x=>!items('strategies').some(s=>s.id===x.strategyId)||!x.nodes.every(Boolean)||!x.justification.trim())))errors.push('Ajoutez un scénario opérationnel et justifiez sa vraisemblance.');if(n===5){let rs=items('risks');if(!rs.length)errors.push('Ajoutez une évaluation de risque.');if(rs.some(r=>!r.decisionReason.trim()))errors.push('Prenez une décision justifiée pour chaque risque.');if(rs.some(r=>r.decision==='Réduire'&&!db.actions.some(a=>a.riskId===r.id)))errors.push('Reliez une action aux risques à réduire.');}if(errors.length){showForm('Atelier incomplet',notice(errors.map(esc).join('<br>'),'red'),()=>true,'Revenir à l’atelier');return;}s.validated[n]=new Date().toISOString();persist('Atelier '+n+' validé',s.name);render();}
function scaleForm(s){let v=s.versions.at(-1);showForm('Nouvelle version · '+s.name,notice('La version '+v.number+' sera conservée ; les études existantes ne seront pas modifiées.')+`<div class="tablewrap"><table class="configlevels"><thead><tr><th>Ordre</th><th>Libellé</th><th>Couleur</th></tr></thead><tbody>${v.levels.map((l,i)=>`<tr><td>${l.order}</td><td><input name="label${i}" aria-label="Libellé du niveau ${i+1}" required value="${esc(l.label)}"></td><td><input type="color" name="color${i}" aria-label="Couleur du niveau ${i+1}" value="${l.color}"></td></tr>`).join('')}</tbody></table></div>`+field('reason','Motif de la nouvelle version','','textarea'),f=>{s.versions.push({number:v.number+1,levels:v.levels.map((l,i)=>({...l,label:ensureText(f['label'+i],'Le libellé'),color:f['color'+i]})),reason:ensureText(f.reason,'Le motif')});persist('Version d’échelle publiée (simulation)',s.name+' v'+(v.number+1));},'Publier la nouvelle version');}
function matrixForm(){let m=db.matrixVersions.at(-1);showForm('Nouvelle version de matrice',notice('Chaque cellule est une correspondance explicite. Les études conservent leur version actuelle.')+[3,2,1].map(r=>`<h4>Ressources ${r}</h4><div class="formrow">`+[1,2,3].map(c=>field('cell'+r+c,'Motivation '+c,m.cells[r-1][c-1],'text',[[1,'Faible'],[2,'Moyenne'],[3,'Élevée']])).join('')+'</div>').join('')+field('reason','Motif','','textarea'),f=>{db.matrixVersions.push({number:m.number+1,cells:[1,2,3].map(r=>[1,2,3].map(c=>+f['cell'+r+c])),reason:ensureText(f.reason,'Le motif')});persist('Version de matrice publiée (simulation)','v'+(m.number+1));},'Publier la nouvelle version');}
function download(name,content,type='application/json'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportCSV(){let rows=['actions','treatments'].includes(ui.route)?db.actions:ui.route==='tasks'?db.tasks:ui.route==='proofs'?db.proofs:ui.route==='risks'?db.risks:['catalog','context','suppliers','roles'].includes(ui.route)?db.catalog.filter(x=>x.kind===ui.catalogKind&&!x.archived):db.records[ui.route]||[];rows=filter(rows);if(!rows.length){toast('Aucune ligne à exporter dans cette vue.');return;}let keys=Object.keys(rows[0]).filter(k=>!['history','runs'].includes(k));let cell=x=>{let s=typeof x==='object'?JSON.stringify(x):String(x??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('ASTRA-'+ui.route+'.csv','\ufeff'+[keys.map(cell).join(';'),...rows.map(r=>keys.map(k=>cell(r[k])).join(';'))].join('\r\n'),'text/csv;charset=utf-8');toast('Export CSV préparé.');}
function guide(){showForm('Guide de test de la maquette',`<div class="guide"><ol><li>Dans <b>Études & parcours</b>, créez une étude fictive.</li><li>Atelier 1 : ajoutez un événement lié à une valeur métier et un support, puis validez.</li><li>Atelier 2 : créez un couple, renseignez activité et décision, testez ligne/cercle/matrice, puis validez.</li><li>Atelier 3 : reliez le couple, un fournisseur et l’événement dans un scénario stratégique.</li><li>Atelier 4 : créez un scénario opérationnel ; modifiez ses nœuds et testez les chemins animés.</li><li>Atelier 5 : créez le risque, une action, puis une décision justifiée. Le résiduel se réévalue explicitement.</li><li>Dans <b>Configuration GRC</b>, créez une version d’échelle ou de matrice. Vérifiez que l’étude garde sa version jusqu’à adoption.</li><li>Rechargez la page, exportez vos essais, puis testez une restauration.</li></ol>${notice('Le parcours EBIOS, les registres, les actions, les récurrences et les versions sont interactifs. Les autres modules proposent seulement des fiches génériques pour tester la navigation. La cartographie dynamique est exclue et l’import ARM est un simulateur sur données fictives.')}<p>Le stockage dépend du navigateur et du chemin du dossier. Pour changer de PC, déplacer le ZIP ou préserver vos essais, utilisez l’export JSON. Évitez toute donnée réelle ou sensible.</p></div>`,()=>true,'Commencer le test');}
function checkBackup(b){if(!b||b.schema!==2||typeof b!=='object')throw Error('Fichier incompatible : sauvegarde ASTRA de maquette v2 attendue.');let arrays=['catalog','scales','matrixVersions','studies','events','pairs','strategies','operations','risks','actions','tasks','proofs','imports','history'];for(let k of arrays)if(!Array.isArray(b[k])||b[k].length>10000)throw Error('Collection invalide : '+k);if(!b.records||typeof b.records!=='object'||Array.isArray(b.records))throw Error('Registres invalides.');function walk(x){if(!x||typeof x!=='object')return;for(let k of Object.keys(x)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Clé interdite dans le fichier.');walk(x[k]);}}walk(b);let allIds=new Set();for(let k of arrays.filter(k=>!['history','imports','matrixVersions'].includes(k))){for(let x of b[k]){if(!x||typeof x.id!=='string'||allIds.has(x.id))throw Error('Identifiant invalide ou dupliqué.');allIds.add(x.id);}}let range=(x,n)=>Number.isInteger(x)&&x>=1&&x<=n;for(let m of b.matrixVersions)if(!range(m.number,10000)||!Array.isArray(m.cells)||m.cells.length!==3||m.cells.some(r=>!Array.isArray(r)||r.length!==3||r.some(v=>!range(v,3))))throw Error('Matrice invalide.');if(!b.matrixVersions.length||!b.scales.length)throw Error('Configurations manquantes.');for(let s of b.scales){if(!Array.isArray(s.versions)||!s.versions.length)throw Error('Échelle sans version.');for(let v of s.versions)if(!Array.isArray(v.levels)||!v.levels.length||v.levels.some(l=>!/^#[\da-f]{6}$/i.test(l.color)||typeof l.label!=='string'))throw Error('Niveau d’échelle invalide.');}for(let s of b.studies)if(!s.validated||!s.notes||!s.scaleVersions||!b.matrixVersions.some(m=>m.number===s.matrixVersion))throw Error('Contexte d’étude invalide.');for(let k of ['events','pairs','strategies','operations','risks'])for(let x of b[k])if(!b.studies.some(s=>s.id===x.studyId))throw Error('Étude référencée absente.');for(let e of b.events)if(typeof e.justification!=='string'||!range(e.gravity,4)||!b.catalog.some(c=>c.id===e.valueId&&c.kind==='value')||!b.catalog.some(c=>c.id===e.assetId&&c.kind==='asset'))throw Error('Événement ou référence invalide.');for(let x of b.strategies)if(typeof x.description!=='string'||!b.pairs.some(p=>p.id===x.pairId&&p.studyId===x.studyId)||!b.events.some(e=>e.id===x.eventId&&e.studyId===x.studyId))throw Error('Scénario stratégique invalide.');for(let p of b.pairs)if(!b.catalog.some(c=>c.id===p.sourceId&&c.kind==='source')||!b.catalog.some(c=>c.id===p.objectiveId&&c.kind==='objective')||!range(p.resources,3)||!range(p.motivation,3)||typeof p.activity!=='string'||typeof p.justification!=='string')throw Error('Couple invalide.');for(let r of b.risks)if(!range(r.gravity,4)||!range(r.likelihood,4)||!Array.isArray(r.history)||typeof r.decisionReason!=='string'||r.residual&&(!range(r.residual.gravity,4)||!range(r.residual.likelihood,4)))throw Error('Risque invalide.');for(let o of b.operations)if(!b.strategies.some(s=>s.id===o.strategyId&&s.studyId===o.studyId)||typeof o.justification!=='string'||!range(o.likelihood,4)||!Array.isArray(o.nodes)||o.nodes.length!==5||o.nodes.some(x=>typeof x!=='string'))throw Error('Scénario invalide.');for(let t of b.tasks)if(!Array.isArray(t.runs))throw Error('Historique de tâche invalide.');for(let rows of Object.values(b.records))if(!Array.isArray(rows))throw Error('Registre invalide.');return true;}
function confirmAction(name,text,callback,label='Confirmer'){showForm(name,notice(text),()=>callback(),label);}
const handlers={
 'mobile':()=>$('#sidebar').classList.toggle('mobile-open'),'guide':guide,'close-dialog':()=>$('#editor').close(),
 'group':e=>{ui.group=ui.group===e.dataset.id?'':e.dataset.id;renderNav();},'go':e=>{ui.group=MENU.find(m=>m[3].some(c=>c[0]===e.dataset.route))?.[0]||'administration';navigate(e.dataset.route);},
 'clear-search':()=>{ui.query='';render();},'new-catalog':()=>formCatalog(),'edit-catalog':e=>formCatalog(db.catalog.find(x=>x.id===e.dataset.id)),
 'catalog-kind':e=>{ui.catalogKind=e.dataset.kind;ui.query='';ui.route='catalog';location.hash='catalog';render();},
 'archive-catalog':e=>{let x=db.catalog.find(x=>x.id===e.dataset.id);let dependent=['studies','events','pairs','strategies','actions'].some(k=>db[k].some(r=>Object.values(r).includes(x.id)));if(dependent){toast('Cette fiche est référencée : conservez-la pour les études existantes.');return;}confirmAction('Archiver la fiche',esc(x.name)+' sera retirée des sélecteurs.',()=>{x.archived=true;persist('Fiche archivée',x.name);});},
 'new-study':()=>formStudy(),'edit-study':e=>formStudy(db.studies.find(x=>x.id===e.dataset.id)),
 'open-study':e=>{ui.studyId=e.dataset.id;ui.step=1;ui.group='risques';navigate('study');},'resume-study':()=>{ui.group='risques';navigate('study');},
 'step':e=>{ui.step=+e.dataset.step;render();},'next-step':()=>{ui.step=Math.min(5,ui.step+1);render();},'validate-step':validateStep,
 'step-note':()=>{let s=requireStudy();showForm('Note de l’atelier '+ui.step,field('note','Note',s.notes[ui.step]||'','textarea',null,false),f=>{s.notes[ui.step]=f.note;persist('Note de l’atelier '+ui.step,s.name);});},
 'new-event':()=>formEvent(),'edit-event':e=>formEvent(db.events.find(x=>x.id===e.dataset.id)),
 'new-pair':()=>formPair(),'edit-pair':e=>formPair(db.pairs.find(x=>x.id===e.dataset.id)),
 'select-pair':e=>{ui.selectedPair=e.dataset.id;ui.emptyCell=false;render();},'select-cell':e=>{let p=items('pairs').find(p=>p.resources===+e.dataset.row&&p.motivation===+e.dataset.col);ui.selectedPair=p?.id||'';ui.emptyCell=!p;render();},
 'new-strategy':()=>formStrategy(),'edit-strategy':e=>formStrategy(db.strategies.find(x=>x.id===e.dataset.id)),
 'new-operation':()=>formOperation(),'edit-operation':e=>formOperation(db.operations.find(x=>x.id===e.dataset.id)),
 'show-operation':e=>{ui.operationId=e.dataset.id;render();},'path':e=>{ui.path=e.dataset.path;render();},
 'new-risk':()=>formRisk(),'edit-risk':e=>{let r=chosenRisk(e);formRisk(r);},'risk-detail':e=>{let r=chosenRisk(e);showForm(r.title,notice(esc(r.justification))+table(['Type','Date','Décision / résultat'],r.history.map(h=>({cells:[esc(h.stage),esc(h.at),esc(h.decision||('G'+h.gravity+' / V'+h.likelihood))]}))),()=>true,'Fermer');},
 'risk-cell':e=>{let r=db.risks.find(r=>r.gravity===+e.dataset.g&&r.likelihood===+e.dataset.v&&(ui.route!=='study'||r.studyId===ui.studyId));ui.selectedRisk=r?.id||'';render();if(!r)toast('Aucun risque dans cette cellule.');},
 'residual':()=>formResidual(chosenRisk()),'decision':e=>formDecision(chosenRisk(e)),
 'new-action':()=>formAction(),'edit-action':e=>formAction(db.actions.find(x=>x.id===e.dataset.id)),
 'action-status':e=>{let a=db.actions.find(x=>x.id===e.dataset.id);a.status=a.status==='Clos'?'Ouvert':'Clos';persist('Statut de l’action modifié',a.title+' · '+a.status);render();},'action-view':e=>{ui.view=e.dataset.view;render();},
 'new-task':()=>formTask(),'edit-task':e=>formTask(db.tasks.find(x=>x.id===e.dataset.id)),
 'run-task':e=>{let t=db.tasks.find(x=>x.id===e.dataset.id);showForm('Enregistrer une réalisation',field('date','Date de réalisation',new Date().toISOString().slice(0,10),'date')+field('note','Compte rendu fictif','','textarea'),f=>{let date=new Date(f.date+'T12:00:00Z');if(t.frequency==='Hebdomadaire')date.setUTCDate(date.getUTCDate()+7);else{let day=date.getUTCDate();date.setUTCDate(1);date.setUTCMonth(date.getUTCMonth()+(t.frequency==='Trimestrielle'?3:1));let last=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();date.setUTCDate(Math.min(day,last));}t.runs.unshift({date:f.date,note:ensureText(f.note,'Le compte rendu')});t.due=date.toISOString().slice(0,10);persist('Réalisation enregistrée',t.title);});},
 'task-history':e=>{let t=db.tasks.find(x=>x.id===e.dataset.id);showForm('Historique · '+t.title,table(['Date','Compte rendu'],t.runs.map(r=>({cells:[esc(r.date),esc(r.note)]}))),()=>true,'Fermer');},
 'new-proof':()=>formProof(),'edit-proof':e=>formProof(db.proofs.find(x=>x.id===e.dataset.id)),
 'new-generic':()=>genericForm(),'edit-generic':e=>genericForm((db.records[ui.route]||[]).find(x=>x.id===e.dataset.id)),
 'archive-generic':e=>{let x=db.records[ui.route].find(x=>x.id===e.dataset.id);confirmAction('Archiver la fiche',esc(x.title),()=>{x.archived=true;persist('Fiche archivée',x.title);});},
 'scale-open':e=>{ui.scaleId=e.dataset.id;navigate('scale');},'scale-edit':e=>scaleForm(db.scales.find(x=>x.id===e.dataset.id)),
 'matrix-edit':matrixForm,'adopt-config':()=>{let s=requireStudy();showForm('Adopter une configuration dans l’étude',notice('Les anciennes valeurs de configuration restent dans le journal. Les validations des ateliers seront à revoir ; aucune évaluation historique n’est effacée.')+field('reason','Motif de l’adoption','','textarea'),f=>{s.contextHistory||=[];s.contextHistory.push({matrixVersion:s.matrixVersion,scaleVersions:clone(s.scaleVersions),pairs:clone(items('pairs')),validated:clone(s.validated),at:new Date().toISOString()});s.matrixVersion=db.matrixVersions.at(-1).number;s.scaleVersions=Object.fromEntries(db.scales.map(sc=>[sc.id,sc.versions.at(-1).number]));invalidate(1);persist('Nouveau contexte adopté',s.name+' · '+ensureText(f.reason,'Le motif'));});},
 'theme':e=>{db.theme=e.dataset.theme;persist('Apparence modifiée',db.theme);render();},
 'prepare-import':()=>{ui.importPrepared=true;render();},'commit-import':()=>{showForm('Résoudre le propriétaire du lot fictif',field('owner','Rôle correspondant','','text',options('role'))+field('reason','Justification du rapprochement','','textarea'),f=>{ensureText(f.reason,'La justification');if(!db.imports.some(i=>i.key==='DEMO-ARM-001')){db.catalog.push({id:'VM-IMPORT-DEMO',kind:'value',name:'Valeur métier importée — FICTIF',category:'Démonstration',owner:cat(f.owner)});db.imports.push({key:'DEMO-ARM-001',at:new Date().toISOString(),reason:f.reason});persist('Lot fictif importé','Une fiche, aucun document ARM réel.');}else toast('Lot déjà importé : aucun doublon créé.');ui.importPrepared=false;},'Valider le lot fictif');},
 'export-backup':()=>{download('ASTRA-mes-essais.json',JSON.stringify(db,null,2));toast('Sauvegarde JSON préparée.');},'export-csv':exportCSV,
 'restore-backup':()=>$('#restore-file').click(),
 'reset':()=>confirmAction('Remettre la maquette à zéro','Vos essais locaux seront remplacés par le jeu fictif initial. Exportez-les avant de confirmer.',()=>{db=clone(ASTRA_SEED);corruptStorage=false;ui.studyId=db.studies[0].id;ui.step=1;ui.selectedPair='';ui.selectedRisk='';persist('Maquette réinitialisée');},'Réinitialiser')
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){try{handlers[el.dataset.act]?.(el);}catch(err){toast(err.message);}return;}let tr=e.target.closest('[data-select]');if(tr){if(tr.dataset.select==='pair'){ui.selectedPair=tr.dataset.id;ui.emptyCell=false;}else ui.selectedRisk=tr.dataset.id;render();}});
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;let el=e.target.closest('tr[data-select],svg [data-act]');if(el){e.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('Fichier trop volumineux : maximum 5 Mo.');let next=JSON.parse(await file.text());checkBackup(next);confirmAction('Restaurer les essais','La sauvegarde contient '+next.studies.length+' étude(s). Elle remplacera les essais locaux actuels.',()=>{db=clone(next);corruptStorage=false;ui.studyId=db.studies.find(x=>!x.archived)?.id||'';ui.selectedPair='';ui.selectedRisk='';persist('Sauvegarde JSON restaurée',file.name);});}catch(err){toast('Import refusé : '+err.message);}});
window.addEventListener('hashchange',()=>{ui.route=location.hash.slice(1)||'dashboard';ui.group=MENU.find(m=>m[3].some(c=>c[0]===ui.route))?.[0]||(['study','scenario-detail'].includes(ui.route)?'risques':'administration');render();});
render();
